import { useEffect, useMemo, useRef, useState } from "react";
import { Archive, Check, ChevronDown, ChevronRight, Download, Edit3, FileSpreadsheet, History, Lock, MoreHorizontal, Plus, RotateCcw, Search, Upload } from "lucide-react";
import { toast } from "sonner";
import * as XLSX from "xlsx";
import { Badge } from "@/components/ui/badge";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Textarea } from "@/components/ui/textarea";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { ActorStamp, GroupChip, NodeFilterEmpty, PathwayRef, PathwayStatusChip, TraceId, useHistorySheet, useNodeFilter } from "@/components/hitl";
import { GROUP_COLOR_TOKENS, NODE_LABELS, affectedPathwayIds, derivedCompanyPathwayIds, derivedPathwayIds, organisations, pathwaysInGroup, sameIndicatorTarget, targetForPathway, useHitlStore, type Group, type GroupColorToken, type Pathway, type PathwayStatus, type VisibilityScope } from "@/lib/hitlStore";
import { cn } from "@/lib/utils";

type NodeKey = "feedstock" | "process_technology" | "product" | "application_market";
type Draft = Pick<Pathway, NodeKey | "group_id">;
const nodeLabels = NODE_LABELS;
const statuses: PathwayStatus[] = ["approved", "needs_approval", "locked", "hidden", "deleted"];
const statusActions = [
  { status: "approved", verb: "Approve" },
  { status: "locked", verb: "Lock" },
  { status: "hidden", verb: "Hide" },
  { status: "deleted", verb: "Delete" },
] as const satisfies { status: PathwayStatus; verb: string }[];
const statusMeaning: Record<PathwayStatus, string> = {
  approved: "Visible and usable.", needs_approval: "Awaiting review.", locked: "Visible to users but not usable; used for sales and marketing.", hidden: "Not visible in Pathway Explorer, counts or benchmarks.", deleted: "Soft-deleted and retained with history.",
};
const blankDraft: Draft = { feedstock: "", process_technology: "", product: "", application_market: "", group_id: null };
const clean = (value: string) => value.trim().toLocaleLowerCase();
const samePathway = (pathway: Pathway, draft: Draft) => (Object.keys(nodeLabels) as NodeKey[]).every(key => clean(pathway[key]) === clean(draft[key]));
const nextId = (pathways: Pathway[]) => `pw-${String(Math.max(0, ...pathways.map(item => Number(item.id.match(/\d+/)?.[0] ?? 0))) + 1).padStart(3, "0")}`;

export function PathwaysSection() {
  const store = useHitlStore();
  const { openHistory } = useHistorySheet();
  const nodeFilter = useNodeFilter();
  const [search, setSearch] = useState(""); const [status, setStatus] = useState("all"); const [group, setGroup] = useState("all"); const [showDeleted, setShowDeleted] = useState(false);
  const [selected, setSelected] = useState<string[]>([]); const [edit, setEdit] = useState<Pathway | "new" | null>(null); const [statusTarget, setStatusTarget] = useState<{ ids: string[]; status: PathwayStatus } | null>(null); const [groupTarget, setGroupTarget] = useState<string[] | null>(null); const [bulkOpen, setBulkOpen] = useState(false); const [bulkGroupOpen, setBulkGroupOpen] = useState(false); const [manageGroupsOpen, setManageGroupsOpen] = useState(false); const [importOpen, setImportOpen] = useState(false); const [highlight, setHighlight] = useState<string | null>(null);
  const activeGroups = useMemo(() => store.groups.filter(item => !item.is_archived).sort((a, b) => a.name.localeCompare(b.name)), [store.groups]);
  const filtered = useMemo(() => store.pathways.filter(item => {
    const haystack = [item.id, item.feedstock, item.process_technology, item.product, item.application_market].join(" ").toLowerCase();
    return nodeFilter.matchesPathway(item) && (showDeleted || item.status !== "deleted") && (!search || haystack.includes(search.toLowerCase())) && (status === "all" || item.status === status) && (group === "all" || (group === "none" ? item.group_id === null : item.group_id === group));
  }), [store.pathways, search, status, group, showDeleted, nodeFilter.feedstock, nodeFilter.product]);
  useEffect(() => setSelected([]), [nodeFilter.feedstock, nodeFilter.product]);
  useEffect(() => { if (!highlight) return; const timer = window.setTimeout(() => setHighlight(null), 2200); return () => window.clearTimeout(timer); }, [highlight]);
  const applyGroup = (ids: string[], value: string | null, note: string | null = null) => { const target = store.groups.find(item => item.id === value); if (target?.is_system) return; const changed = ids.map(id => store.pathways.find(row => row.id === id)).filter((item): item is Pathway => Boolean(item && item.group_id !== value)); changed.forEach(item => store.recordChange({ entity_type: "pathway", entity_id: item.id, field: "group_id", prior_value: item.group_id, new_value: value, operation: "update", note })); toast.success(`${changed.length} pathway${changed.length === 1 ? "" : "s"} updated`); setSelected([]); };
  return <>
    <div className="flex flex-wrap items-center gap-2 border-b px-4 py-3"><div className="relative min-w-64 flex-1"><Search className="absolute left-2.5 top-2 h-3.5 w-3.5 text-muted-foreground" /><Input className="h-8 pl-8 text-xs" placeholder="Search pathways…" value={search} onChange={event => setSearch(event.target.value)} /></div>
      <SimpleSelect value={status} onChange={setStatus} label="Status"><SelectItem value="all">All statuses</SelectItem>{statuses.map(item => <SelectItem key={item} value={item}>{item.replace("_", " ")}</SelectItem>)}</SimpleSelect>
      <SimpleSelect value={group} onChange={setGroup} label="Group"><SelectItem value="all">All groups</SelectItem><SelectItem value="none">No group</SelectItem>{activeGroups.map(item => <SelectItem key={item.id} value={item.id}>{item.name}</SelectItem>)}{showDeleted && store.groups.some(item => item.is_archived) && <SelectItem disabled value="archived-label">Archived groups</SelectItem>}{showDeleted && store.groups.filter(item => item.is_archived).map(item => <SelectItem key={item.id} value={item.id}>{item.name} (archived)</SelectItem>)}</SimpleSelect>
      <label className="flex items-center gap-2 text-[10px] text-muted-foreground"><Switch className="scale-75" checked={showDeleted} onCheckedChange={setShowDeleted} />Show deleted</label>
      <Button size="sm" variant="outline" className="h-8 text-[10px]" onClick={() => setManageGroupsOpen(true)}>Manage groups</Button><Button size="sm" variant="outline" className="h-8 text-[10px]" onClick={() => setBulkGroupOpen(true)}>Bulk assign group</Button><Button size="sm" variant="outline" className="h-8 text-[10px]" onClick={() => setImportOpen(true)}><FileSpreadsheet className="mr-1 h-3 w-3" />Import Excel</Button><Button size="sm" variant="outline" className="h-8 text-[10px]" onClick={() => setBulkOpen(true)}>Bulk deactivate</Button><Button size="sm" className="h-8 text-[10px]" onClick={() => setEdit("new")}><Plus className="mr-1 h-3 w-3" />New pathway</Button>
    </div>
    {selected.length > 0 && <div className="sticky top-0 z-10 flex flex-wrap items-center gap-2 border-b bg-background px-4 py-2 shadow-sm"><span className="text-xs font-medium">{selected.length} selected</span><BulkStatus onChoose={value => setStatusTarget({ ids: selected, status: value })} /><Button variant="outline" size="sm" className="h-7 text-[10px]" onClick={() => setGroupTarget(selected)}>Assign group <ChevronDown className="ml-1 h-3 w-3" /></Button><Button variant="link" size="sm" className="h-7 text-[10px]" onClick={() => setSelected([])}>Clear selection</Button></div>}
    <div className="overflow-x-auto"><Table className="min-w-[1380px]"><TableHeader><TableRow><TableHead className="sticky left-0 z-20 w-9 min-w-9 bg-background"><Checkbox checked={filtered.length > 0 && filtered.every(item => selected.includes(item.id))} onCheckedChange={checked => setSelected(checked ? filtered.map(item => item.id) : [])} /></TableHead><TableHead>ID</TableHead><TableHead>{NODE_LABELS.feedstock}</TableHead><TableHead>{NODE_LABELS.process_technology}</TableHead><TableHead>{NODE_LABELS.product}</TableHead><TableHead>{NODE_LABELS.application_market}</TableHead><TableHead className="min-w-[9.5rem] whitespace-nowrap">Status</TableHead><TableHead className="min-w-32 whitespace-nowrap">Group</TableHead><TableHead>Visibility</TableHead><TableHead>Last change</TableHead><TableHead>Trace</TableHead><TableHead className="sticky right-0 z-20 min-w-32 bg-background text-right">Actions</TableHead></TableRow></TableHeader><TableBody>
      {filtered.map(item => <TableRow key={item.id} id={`pathway-row-${item.id}`} className={cn("transition-colors", highlight === item.id && "bg-primary/10")}><TableCell className="sticky left-0 z-10 bg-background"><Checkbox checked={selected.includes(item.id)} onCheckedChange={checked => setSelected(rows => checked ? [...rows, item.id] : rows.filter(id => id !== item.id))} /></TableCell><TableCell className="font-mono text-[10px]">{item.id}</TableCell><Cell>{item.feedstock}</Cell><Cell>{item.process_technology}</Cell><Cell>{item.product}</Cell><Cell>{item.application_market}</Cell><TableCell className="min-w-[9.5rem] whitespace-nowrap"><PathwayStatusChip status={item.status} /></TableCell><TableCell className="min-w-32 whitespace-nowrap"><GroupChip groupId={item.group_id} onClick={item.group_id ? () => setGroup(item.group_id ?? "all") : undefined} /></TableCell><TableCell className="text-[10px]">{item.visibility_scope === "all" ? "All users" : <Tooltip><TooltipTrigger asChild><span className="cursor-help underline decoration-dotted">{item.visibility_scope.length} organisations</span></TooltipTrigger><TooltipContent>{item.visibility_scope.join(", ")}</TooltipContent></Tooltip>}</TableCell><TableCell><ActorStamp name={item.last_actor ?? "System"} timestamp={item.updated_at} /></TableCell><TableCell><TraceId value={item.trace_id} /></TableCell><TableCell className="sticky right-0 z-10 bg-background"><div className="flex justify-end gap-1"><Button variant="ghost" size="icon" className="h-7 w-7" aria-label={`History for ${item.id}`} onClick={() => openHistory("pathway", item.id)}><History className="h-3.5 w-3.5" /></Button><Button variant="ghost" size="icon" className="h-7 w-7" aria-label={`Edit ${item.id}`} onClick={() => setEdit(item)}><Edit3 className="h-3.5 w-3.5" /></Button><DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon" className="h-7 w-7" aria-label={`More actions for ${item.id}`}><MoreHorizontal className="h-3.5 w-3.5" /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuLabel className="text-[10px] font-normal text-muted-foreground">Set status</DropdownMenuLabel>{statusActions.filter(action => action.status !== item.status).map(action => <DropdownMenuItem key={action.status} onSelect={() => setStatusTarget({ ids: [item.id], status: action.status })}>{action.verb}</DropdownMenuItem>)}</DropdownMenuContent></DropdownMenu></div></TableCell></TableRow>)}
      {filtered.length === 0 && <TableRow><TableCell colSpan={12} className="p-0">{nodeFilter.isActive ? <NodeFilterEmpty rows="pathways" /> : <div className="flex h-32 items-center justify-center text-xs text-muted-foreground">No pathways match these filters.</div>}</TableCell></TableRow>}
    </TableBody></Table></div>
    <PathwayDialog open={edit !== null} pathway={edit === "new" ? null : edit} groups={store.groups} pathways={store.pathways} onClose={() => setEdit(null)} onDuplicate={id => { setEdit(null); setShowDeleted(true); setHighlight(id); window.setTimeout(() => document.getElementById(`pathway-row-${id}`)?.scrollIntoView({ behavior: "smooth", block: "center" }), 50); }} />
    <StatusDialog target={statusTarget} pathways={store.pathways} onClose={() => setStatusTarget(null)} afterSave={() => setSelected([])} />
    <AssignGroupDialog ids={groupTarget} groups={store.groups} pathways={store.pathways} onClose={() => setGroupTarget(null)} onSave={value => { if (groupTarget) applyGroup(groupTarget, value); }} />
    <ManageGroupsSheet open={manageGroupsOpen} onClose={() => setManageGroupsOpen(false)} onFilter={id => { setGroup(id); setManageGroupsOpen(false); }} />
    <BulkAssignGroupDialog open={bulkGroupOpen} groups={store.groups} pathways={store.pathways} onClose={() => setBulkGroupOpen(false)} onSave={(ids, value, note) => applyGroup(ids, value, note)} />
    <BulkDeactivateDialog open={bulkOpen} onClose={() => setBulkOpen(false)} pathways={store.pathways} />
    <ImportExcelDialog open={importOpen} onClose={() => setImportOpen(false)} pathways={store.pathways} />
  </>;
}

function Cell({ children }: { children: React.ReactNode }) { return <TableCell className="max-w-48 truncate text-[10px]" title={String(children)}>{children}</TableCell>; }
function SimpleSelect({ value, onChange, label, children, className }: { value: string; onChange: (value: string) => void; label: string; children: React.ReactNode; className?: string }) { return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} className={cn("h-8 w-40 text-[10px]", className)}><SelectValue /></SelectTrigger><SelectContent>{children}</SelectContent></Select>; }
function BulkStatus({ onChoose }: { onChoose: (status: PathwayStatus) => void }) { return <DropdownMenu><DropdownMenuTrigger asChild><Button variant="outline" size="sm" className="h-7 text-[10px]">Set status <ChevronDown className="ml-1 h-3 w-3" /></Button></DropdownMenuTrigger><DropdownMenuContent>{statusActions.map(action => <DropdownMenuItem key={action.status} onSelect={() => onChoose(action.status)}>{action.verb}</DropdownMenuItem>)}</DropdownMenuContent></DropdownMenu>; }

function NodeCombobox({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) {
  const [focused, setFocused] = useState(false);
  const normalized = value.trim();
  const exact = options.find(option => clean(option) === clean(normalized));
  const suggestions = options.filter(option => option.toLocaleLowerCase().includes(normalized.toLocaleLowerCase())).slice(0, 8);
  const isNew = Boolean(normalized) && !exact;
  const commit = () => { onChange(exact ?? normalized); setFocused(false); };
  return <div className="space-y-1.5"><Label className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">{label}</Label><div className="relative"><Input value={value} onFocus={() => setFocused(true)} onChange={event => { onChange(event.target.value); setFocused(true); }} onBlur={() => window.setTimeout(commit, 100)} onKeyDown={event => { if (event.key === "Enter") { event.preventDefault(); commit(); } }} placeholder={`Enter ${label.toLowerCase()}…`} className={cn("h-9 pr-20 text-xs", !normalized && "border-destructive/50")} />{isNew && <Badge variant="outline" className="pointer-events-none absolute right-2 top-1/2 inline-flex h-6 -translate-y-1/2 items-center gap-1 whitespace-nowrap px-2 text-xs text-muted-foreground">New node</Badge>}{focused && suggestions.length > 0 && <div className="absolute z-[110] mt-1 max-h-44 w-full overflow-y-auto rounded-md border bg-popover p-1 text-popover-foreground shadow-md">{suggestions.map(option => <Button key={option} type="button" variant="ghost" className="h-auto w-full justify-start px-2 py-1.5 text-left text-xs" onMouseDown={event => event.preventDefault()} onClick={() => { onChange(option); setFocused(false); }}><Check className={cn("mr-2 h-3 w-3", exact === option ? "opacity-100" : "opacity-0")} />{option}</Button>)}</div>}</div>{!normalized && <p className="text-[10px] text-destructive">Required</p>}</div>;
}

function PathwayDialog({ open, pathway, groups, pathways, onClose, onDuplicate }: { open: boolean; pathway: Pathway | null; groups: Group[]; pathways: Pathway[]; onClose: () => void; onDuplicate: (id: string) => void }) {
  const store = useHitlStore(); const [draft, setDraft] = useState<Draft>(blankDraft); const [groupDialog, setGroupDialog] = useState(false); const [error, setError] = useState<Pathway | null>(null); const [step, setStep] = useState<"form" | "consequences">("form"); const [impact, setImpact] = useState("rerun");
  useEffect(() => { if (!open) return; setDraft(pathway ? { feedstock: pathway.feedstock, process_technology: pathway.process_technology, product: pathway.product, application_market: pathway.application_market, group_id: pathway.group_id } : blankDraft); setError(null); setStep("form"); setImpact("rerun"); }, [open, pathway]);
  const options = useMemo(() => Object.fromEntries((Object.keys(nodeLabels) as NodeKey[]).map(key => [key, [...new Set(pathways.map(item => item[key]))].sort()])), [pathways]) as Record<NodeKey, string[]>;
  const changedNodes = pathway ? (Object.keys(nodeLabels) as NodeKey[]).filter(key => pathway[key] !== draft[key].trim()) : [];
  const nextPathway = pathway ? { ...pathway, ...Object.fromEntries((Object.keys(nodeLabels) as NodeKey[]).map(key => [key, draft[key].trim()])) } : null;
  const nextPathways = pathway && nextPathway ? store.pathways.map(item => item.id === pathway.id ? nextPathway : item) : store.pathways;
  const companyBefore = pathway ? store.companies.filter(item => derivedCompanyPathwayIds(item, store.pathways).includes(pathway.id)) : [];
  const companyAfter = pathway ? store.companies.filter(item => derivedCompanyPathwayIds(item, nextPathways).includes(pathway.id)) : [];
  const evidenceBefore = pathway ? store.paperPatentMatches.filter(item => derivedPathwayIds(item, store.pathways).includes(pathway.id)) : [];
  const evidenceAfter = pathway ? store.paperPatentMatches.filter(item => derivedPathwayIds(item, nextPathways).includes(pathway.id)) : [];
  const indicatorsBefore = pathway ? store.indicatorValues.filter(item => affectedPathwayIds(item, store.pathways).includes(pathway.id)) : [];
  const indicatorsAfter = pathway ? store.indicatorValues.filter(item => affectedPathwayIds(item, nextPathways).includes(pathway.id)) : [];
  const applicationScoped = pathway ? store.indicatorValues.filter(item => item.scope === "application" && sameIndicatorTarget(item.target, targetForPathway("application", pathway))) : [];
  const diffText = <T extends { id: string }>(before: T[], after: T[]) => ({ added: after.filter(item => !before.some(previous => previous.id === item.id)), removed: before.filter(item => !after.some(next => next.id === item.id)) });
  const validate = () => { const duplicate = pathways.find(item => item.id !== pathway?.id && samePathway(item, draft)); setError(duplicate ?? null); return !duplicate; };
  const save = () => {
    if (!validate()) return; const trimmed = Object.fromEntries((Object.keys(nodeLabels) as NodeKey[]).map(key => [key, draft[key].trim()])) as Record<NodeKey, string>;
    if (!pathway) { const now = new Date().toISOString(); const id = nextId(pathways); const record: Pathway = { id, ...draft, ...trimmed, status: "needs_approval", visibility_scope: "all", created_at: now, updated_at: now, status_changed_at: now, last_actor: store.currentUser.name, trace_id: null }; store.recordChange({ entity_type: "pathway", entity_id: id, field: null, prior_value: null, new_value: record, operation: "create", note: "Enrichment and matching queued" }); toast.success(`Pathway ${id} created. Enrichment and matching queued.`); onClose(); return; }
    if (changedNodes.length && step === "form") { setStep("consequences"); return; }
    const note = changedNodes.length ? impact === "rerun" ? "Re-run matching after node change" : impact === "keep" ? "Keep accepted decisions; re-run remaining matches" : "flagged after node change" : null;
    changedNodes.forEach(key => store.recordChange({ entity_type: "pathway", entity_id: pathway.id, field: key, prior_value: pathway[key], new_value: trimmed[key], operation: "update", note }));
    if (draft.group_id !== pathway.group_id) store.recordChange({ entity_type: "pathway", entity_id: pathway.id, field: "group_id", prior_value: pathway.group_id, new_value: draft.group_id, operation: "update" });
    if (changedNodes.length) applicationScoped.forEach(item => { if (impact === "keep" && item.status === "accepted") return; store.recordChange({ entity_type: "indicator_value", entity_id: item.id, field: "status", prior_value: item.status, new_value: "review_pending", operation: "update", note }); });
    toast.success(changedNodes.length ? `Pathway updated; ${applicationScoped.length} Application-scope indicator values processed.` : "Pathway updated."); onClose();
  };
  const ready = (Object.keys(nodeLabels) as NodeKey[]).every(key => draft[key].trim());
  return <Dialog open={open} onOpenChange={value => { if (!value) onClose(); }}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-xl"><DialogHeader><DialogTitle>{pathway ? `Edit pathway ${pathway.id}` : "New pathway"}</DialogTitle><DialogDescription>{step === "form" ? "Define all four Pathway nodes using full labels." : "Consequences of node change"}</DialogDescription></DialogHeader>
    {step === "form" ? <div className="space-y-4">{(Object.keys(nodeLabels) as NodeKey[]).map(key => <NodeCombobox key={key} label={nodeLabels[key]} value={draft[key]} options={options[key]} onChange={value => setDraft(item => ({ ...item, [key]: value }))} />)}<div className="space-y-1.5"><Label className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Group (optional)</Label><SimpleSelect value={draft.group_id ?? "none"} onChange={value => value === "create" ? setGroupDialog(true) : setDraft(item => ({ ...item, group_id: value === "none" ? null : value }))} label="Group" className="w-full"><SelectItem value="none">No group</SelectItem>{groups.filter(item => !item.is_archived).map(item => <SelectItem key={item.id} value={item.id} disabled={item.is_system}>{item.is_system ? "🔒 " : ""}{item.name}</SelectItem>)}<SelectItem value="create">Create group…</SelectItem></SimpleSelect></div>{pathway ? <div><span className="text-[10px] text-muted-foreground">Status</span><div className="mt-1"><PathwayStatusChip status={pathway.status} /></div></div> : <div className="flex items-center gap-2 text-xs"><span className="text-muted-foreground">Status</span><PathwayStatusChip status="needs_approval" /></div>}{error && <div className="space-y-2 rounded-md border border-destructive/30 bg-destructive/5 p-2 text-xs text-destructive"><div className="flex items-center justify-between"><span>Duplicate of {error.id}</span><Button variant="link" className="h-auto p-0 text-xs" onClick={() => onDuplicate(error.id)}>Open {error.id}</Button></div><PathwayRef pathwayId={error.id} variant="inline" /></div>}</div> : <div className="space-y-4">{pathway && <div className="grid gap-3 sm:grid-cols-2"><div><p className="mb-1 text-[10px] font-medium text-muted-foreground">Before</p><PathwayRef pathwayId={pathway.id} pathway={pathway} variant="card" emphasisNodes={changedNodes} /></div><div><p className="mb-1 text-[10px] font-medium text-muted-foreground">After</p><PathwayRef pathwayId={pathway.id} pathway={{ ...pathway, ...Object.fromEntries((Object.keys(nodeLabels) as NodeKey[]).map(key => [key, draft[key].trim()])) }} variant="card" emphasisNodes={changedNodes} /></div></div>}<div className="space-y-2 rounded-md border p-3"><h3 className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Re-derived automatically</h3>{[["Companies", companyBefore, companyAfter], ["Papers and patents", evidenceBefore, evidenceAfter], ["Indicator values", indicatorsBefore, indicatorsAfter]].map(([label, before, after]) => { const change = diffText(before as { id: string }[], after as { id: string }[]); return <div key={String(label)} className="text-[10px]"><strong>{label as string}</strong>: {(before as { id: string }[]).length} before · {(after as { id: string }[]).length} after <span className="text-muted-foreground">· added {change.added.map(item => item.id).join(", ") || "none"} · removed {change.removed.map(item => item.id).join(", ") || "none"}</span></div>; })}</div><div className="space-y-2 rounded-md border p-3"><h3 className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Application-scope indicator values ({applicationScoped.length})</h3><RadioGroup value={impact} onValueChange={setImpact} className="space-y-2">{[["rerun", "Re-run matching"], ["keep", "Keep accepted decisions, re-run the rest"], ["flag", "Flag everything for review, no re-run"]].map(([value, label]) => <label key={value} className="flex items-start gap-2 rounded-md border p-3 text-xs"><RadioGroupItem value={value} /><span>{label}</span></label>)}</RadioGroup></div></div>}
    <DialogFooter>{step === "consequences" && <Button variant="outline" onClick={() => setStep("form")}>Back</Button>}<Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={!ready} onClick={save}>{step === "consequences" ? "Save and apply" : "Save"}</Button></DialogFooter>
  </DialogContent><GroupEditorDialog open={groupDialog} group={null} onClose={() => setGroupDialog(false)} onSaved={id => { setDraft(item => ({ ...item, group_id: id })); setGroupDialog(false); }} /></Dialog>;
}

function VisibilityControl({ value, onChange }: { value: VisibilityScope; onChange: (value: VisibilityScope) => void }) { const selected = value === "all" ? [] : value; return <div className="space-y-2"><Label className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Visibility scope</Label><RadioGroup value={value === "all" ? "all" : "selected"} onValueChange={choice => onChange(choice === "all" ? "all" : [])}><label className="flex items-center gap-2 text-xs"><RadioGroupItem value="all" />All users</label><label className="flex items-center gap-2 text-xs"><RadioGroupItem value="selected" />Selected organisations</label></RadioGroup>{value !== "all" && <div className="grid grid-cols-1 gap-1 rounded-md border p-2 sm:grid-cols-2">{organisations().map(org => <label key={org} className="flex items-center gap-2 text-[10px]"><Checkbox checked={selected.includes(org)} onCheckedChange={checked => onChange(checked ? [...selected, org] : selected.filter(item => item !== org))} />{org}</label>)}</div>}</div>; }

function StatusDialog({ target, pathways, onClose, afterSave }: { target: { ids: string[]; status: PathwayStatus } | null; pathways: Pathway[]; onClose: () => void; afterSave: () => void }) { const store = useHitlStore(); const [note, setNote] = useState(""); const [visibility, setVisibility] = useState<VisibilityScope>("all"); useEffect(() => { if (target) { setNote(""); const first = pathways.find(item => item.id === target.ids[0]); setVisibility(first?.visibility_scope ?? "all"); } }, [target, pathways]); const save = () => { if (!target) return; target.ids.forEach(id => { const item = pathways.find(row => row.id === id); if (!item) return; store.recordChange({ entity_type: "pathway", entity_id: id, field: "status", prior_value: item.status, new_value: target.status, operation: ["locked", "hidden", "deleted"].includes(target.status) ? "deactivate" : "update", note }); if (target.status !== "approved" && JSON.stringify(item.visibility_scope) !== JSON.stringify(visibility)) store.recordChange({ entity_type: "pathway", entity_id: id, field: "visibility_scope", prior_value: item.visibility_scope, new_value: visibility, operation: "update", note }); }); toast.success(`${target.ids.length} pathway${target.ids.length === 1 ? "" : "s"} updated`); onClose(); afterSave(); }; const verb = target ? statusActions.find(action => action.status === target.status)?.verb ?? "Set status for" : "Set status for"; return <Dialog open={target !== null} onOpenChange={open => { if (!open) onClose(); }}><DialogContent><DialogHeader><DialogTitle>{target ? `${verb} ${target.ids.length === 1 ? "pathway" : `${target.ids.length} pathways`}` : "Set pathway status"}</DialogTitle><DialogDescription>{target && statusMeaning[target.status]}</DialogDescription></DialogHeader>{target && <div className="space-y-4"><PathwayStatusChip status={target.status} />{target.status !== "approved" && <VisibilityControl value={visibility} onChange={setVisibility} />}<div><Label className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Note (optional)</Label><Textarea value={note} onChange={event => setNote(event.target.value)} className="mt-1 text-xs" /></div></div>}<DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button onClick={save}>Save</Button></DialogFooter></DialogContent></Dialog>; }

function GroupOptions({ groups, value, onChange, includeCreate = false, onCreate }: { groups: Group[]; value: string; onChange: (value: string | null) => void; includeCreate?: boolean; onCreate?: () => void }) {
  return <RadioGroup value={value} onValueChange={next => next === "create" ? onCreate?.() : onChange(next === "none" ? null : next)} className="space-y-1.5">
    <label className="flex items-center gap-2 rounded-md border p-2 text-xs"><RadioGroupItem value="none" /><span>No group</span></label>
    {groups.filter(group => !group.is_archived).map(group => <Tooltip key={group.id}><TooltipTrigger asChild><label className={cn("flex items-center gap-2 rounded-md border p-2", group.is_system && "cursor-not-allowed opacity-55")}><RadioGroupItem value={group.id} disabled={group.is_system} /><GroupChip group={group} /></label></TooltipTrigger>{group.is_system && <TooltipContent>Membership is rule-derived</TooltipContent>}</Tooltip>)}
    {includeCreate && <label className="flex items-center gap-2 rounded-md border p-2 text-xs"><RadioGroupItem value="create" /><Plus className="h-3.5 w-3.5" />Create group…</label>}
  </RadioGroup>;
}

function GroupEditorDialog({ open, group, onClose, onSaved }: { open: boolean; group: Group | null; onClose: () => void; onSaved?: (id: string) => void }) {
  const store = useHitlStore(); const [name, setName] = useState(""); const [color, setColor] = useState<GroupColorToken>(GROUP_COLOR_TOKENS[0]); const [visibility, setVisibility] = useState<VisibilityScope>("all"); const [description, setDescription] = useState("");
  useEffect(() => { if (!open) return; setName(group?.name ?? ""); setColor(group?.color_token ?? GROUP_COLOR_TOKENS[0]); setVisibility(group?.visibility_scope ?? "all"); setDescription(group?.description ?? ""); }, [open, group]);
  const duplicate = store.groups.some(item => item.id !== group?.id && item.name.trim().toLocaleLowerCase() === name.trim().toLocaleLowerCase()); const invalidVisibility = visibility !== "all" && visibility.length === 0; const readonly = Boolean(group?.is_system);
  const save = () => { if (!name.trim() || duplicate || invalidVisibility || readonly) return; if (!group) { const now = new Date().toISOString(); const id = `grp-${String(Math.max(0, ...store.groups.map(item => Number(item.id.match(/\d+/)?.[0] ?? 0))) + 1).padStart(3, "0")}`; const value: Group = { id, name: name.trim(), color_token: color, visibility_scope: visibility, description: description.trim() || null, is_system: false, is_archived: false, created_at: now, updated_at: now, status_changed_at: now, last_actor: store.currentUser.name, trace_id: null }; store.recordChange({ entity_type: "group", entity_id: id, field: null, prior_value: null, new_value: value, operation: "create" }); toast.success(`Group ${value.name} saved`); onSaved?.(id); onClose(); return; } (["name", "color_token", "visibility_scope", "description"] as const).forEach(field => { const next = field === "name" ? name.trim() : field === "color_token" ? color : field === "visibility_scope" ? visibility : description.trim() || null; if (JSON.stringify(group[field]) !== JSON.stringify(next)) store.recordChange({ entity_type: "group", entity_id: group.id, field, prior_value: group[field], new_value: next, operation: "update" }); }); toast.success(`Group ${name.trim()} saved`); onSaved?.(group.id); onClose(); };
  return <Dialog open={open} onOpenChange={value => { if (!value) onClose(); }}><DialogContent><DialogHeader><DialogTitle>{group ? `Edit ${group.name}` : "New group"}</DialogTitle><DialogDescription>{group?.is_system ? "System group — rule-derived, not editable here" : "Set the group name, colour, visibility and description."}</DialogDescription></DialogHeader>{group?.is_system && <div className="flex items-center gap-2 rounded-md border bg-muted p-3 text-xs"><Lock className="h-4 w-4" />System group — rule-derived, not editable here</div>}<fieldset disabled={readonly} className="space-y-4"><div><Label>Name</Label><Input value={name} onChange={event => setName(event.target.value)} className="mt-1" />{duplicate && <p className="mt-1 text-xs text-destructive">Name already used</p>}</div><div><Label>Colour</Label><RadioGroup value={color} onValueChange={value => setColor(value as GroupColorToken)} className="mt-2 grid grid-cols-2 gap-2">{GROUP_COLOR_TOKENS.map(token => <label key={token} className="flex items-center gap-2 rounded-md border p-2 text-xs"><RadioGroupItem value={token} /><span className={cn("h-3 w-3 rounded-full", `bg-${token}-fill`)} />{token}</label>)}</RadioGroup></div><VisibilityControl value={visibility} onChange={setVisibility} />{invalidVisibility && <p className="text-xs text-destructive">Select at least one organisation</p>}<div><Label>Description (optional)</Label><Textarea value={description} onChange={event => setDescription(event.target.value)} className="mt-1" /></div></fieldset><DialogFooter><Button variant="outline" onClick={onClose}>Close</Button>{!readonly && <Button disabled={!name.trim() || duplicate || invalidVisibility} onClick={save}>Save</Button>}</DialogFooter></DialogContent></Dialog>;
}

function AssignGroupDialog({ ids, groups, pathways, onClose, onSave }: { ids: string[] | null; groups: Group[]; pathways: Pathway[]; onClose: () => void; onSave: (groupId: string | null) => void }) { const [value, setValue] = useState<string | null>(null); const [creating, setCreating] = useState(false); useEffect(() => { if (ids) setValue(null); }, [ids]); const already = ids?.filter(id => pathways.find(item => item.id === id)?.group_id === value).length ?? 0; const total = ids?.length ?? 0; return <><Dialog open={ids !== null} onOpenChange={open => { if (!open) onClose(); }}><DialogContent><DialogHeader><DialogTitle>Assign group</DialogTitle><DialogDescription>Assign, reassign or clear selected pathways.</DialogDescription></DialogHeader><GroupOptions groups={groups} value={value ?? "none"} onChange={setValue} includeCreate onCreate={() => setCreating(true)} /><p className="text-xs text-muted-foreground">{total} selected · {already} already in this group · {total - already} will change</p><DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={total - already === 0} onClick={() => onSave(value)}>Assign group</Button></DialogFooter></DialogContent></Dialog><GroupEditorDialog open={creating} group={null} onClose={() => setCreating(false)} onSaved={id => setValue(id)} /></>; }

function ManageGroupsSheet({ open, onClose, onFilter }: { open: boolean; onClose: () => void; onFilter: (id: string) => void }) { const store = useHitlStore(); const { openHistory } = useHistorySheet(); const [search, setSearch] = useState(""); const [showArchived, setShowArchived] = useState(false); const [editing, setEditing] = useState<Group | "new" | null>(null); const [archiving, setArchiving] = useState<Group | null>(null); const rows = store.groups.filter(group => (showArchived || !group.is_archived) && group.name.toLocaleLowerCase().includes(search.toLocaleLowerCase())); const archive = () => { if (!archiving || archiving.is_system) return; store.recordChange({ entity_type: "group", entity_id: archiving.id, field: "is_archived", prior_value: archiving.is_archived, new_value: !archiving.is_archived, operation: "update" }); toast.success(`${archiving.name} ${archiving.is_archived ? "restored" : "archived"}`); setArchiving(null); };
  return <><Sheet open={open} onOpenChange={value => { if (!value) onClose(); }}><SheetContent className="flex w-[min(96vw,900px)] flex-col gap-0 p-0 sm:max-w-[900px]"><SheetHeader className="border-b px-5 py-4"><SheetTitle>Manage groups</SheetTitle><SheetDescription>Create, edit, archive and review pathway groups.</SheetDescription></SheetHeader><div className="flex items-center gap-2 border-b p-4"><div className="relative flex-1"><Search className="absolute left-2.5 top-2.5 h-3.5 w-3.5 text-muted-foreground" /><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search groups…" className="h-8 pl-8 text-xs" /></div><label className="flex items-center gap-2 whitespace-nowrap text-xs text-muted-foreground"><Switch checked={showArchived} onCheckedChange={setShowArchived} />Show archived</label><Button size="sm" onClick={() => setEditing("new")}><Plus className="mr-1 h-3.5 w-3.5" />New group</Button></div><div className="flex-1 overflow-auto"><Table className="min-w-[800px]"><TableHeader><TableRow><TableHead>Group</TableHead><TableHead>Visibility</TableHead><TableHead>Pathways</TableHead><TableHead>Type</TableHead><TableHead>Last change</TableHead><TableHead className="text-right">Actions</TableHead></TableRow></TableHeader><TableBody>{rows.map(group => { const count = pathwaysInGroup(store.pathways, group.id).length; return <TableRow key={group.id}><TableCell><GroupChip group={group} /></TableCell><TableCell className="text-xs">{group.visibility_scope === "all" ? "All users" : <Tooltip><TooltipTrigger asChild><span className="underline decoration-dotted">{group.visibility_scope.length} organisations</span></TooltipTrigger><TooltipContent>{group.visibility_scope.join(", ")}</TooltipContent></Tooltip>}</TableCell><TableCell><Button variant="link" className="h-auto p-0 text-xs" onClick={() => onFilter(group.id)}>{count}</Button></TableCell><TableCell className="text-xs">{group.is_system ? <span className="inline-flex items-center gap-1"><Lock className="h-3 w-3" />System</span> : "User"}</TableCell><TableCell><ActorStamp name={group.last_actor ?? "System"} timestamp={group.updated_at} /></TableCell><TableCell><div className="flex justify-end gap-1"><Button variant="ghost" size="icon" aria-label={`Edit ${group.name}`} onClick={() => setEditing(group)}><Edit3 className="h-3.5 w-3.5" /></Button>{!group.is_system && <Button variant="ghost" size="icon" aria-label={`${group.is_archived ? "Restore" : "Archive"} ${group.name}`} onClick={() => setArchiving(group)}>{group.is_archived ? <RotateCcw className="h-3.5 w-3.5" /> : <Archive className="h-3.5 w-3.5" />}</Button>}<Button variant="ghost" size="icon" aria-label={`History for ${group.name}`} onClick={() => openHistory("group", group.id)}><History className="h-3.5 w-3.5" /></Button></div></TableCell></TableRow>; })}</TableBody></Table></div></SheetContent></Sheet><GroupEditorDialog open={editing !== null} group={editing === "new" ? null : editing} onClose={() => setEditing(null)} /><AlertDialog open={archiving !== null} onOpenChange={value => { if (!value) setArchiving(null); }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{archiving?.is_archived ? `Restore ${archiving.name}?` : `Archive ${archiving?.name}?`}</AlertDialogTitle><AlertDialogDescription>{archiving?.is_archived ? "This group will return to group selects." : `${archiving ? pathwaysInGroup(store.pathways, archiving.id).length : 0} pathways keep their assignment and show the group as archived. Nothing is deleted.`}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Cancel</AlertDialogCancel><AlertDialogAction onClick={archive}>{archiving?.is_archived ? "Restore" : "Archive"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>; }

function BulkAssignGroupDialog({ open, groups, pathways, onClose, onSave }: { open: boolean; groups: Group[]; pathways: Pathway[]; onClose: () => void; onSave: (ids: string[], groupId: string | null, note: string | null) => void }) { const [dimension, setDimension] = useState<NodeKey>("feedstock"); const values = [...new Set(pathways.map(item => item[dimension]))].sort(); const [value, setValue] = useState(""); const [groupId, setGroupId] = useState<string | null>(null); const [note, setNote] = useState(""); const [expanded, setExpanded] = useState(false); useEffect(() => { setValue(values[0] ?? ""); }, [dimension]); const matches = pathways.filter(item => item[dimension] === value); const already = matches.filter(item => item.group_id === groupId).length; return <Dialog open={open} onOpenChange={next => { if (!next) onClose(); }}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>Bulk assign group</DialogTitle><DialogDescription>Assign pathways matching one node value.</DialogDescription></DialogHeader><div className="grid grid-cols-2 gap-3"><SimpleSelect value={dimension} onChange={value => setDimension(value as NodeKey)} label="Dimension" className="w-full">{(Object.keys(NODE_LABELS) as NodeKey[]).map(key => <SelectItem key={key} value={key}>{NODE_LABELS[key]}</SelectItem>)}</SimpleSelect><SimpleSelect value={value} onChange={setValue} label="Value" className="w-full">{values.map(item => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SimpleSelect></div><div className="max-h-64 overflow-y-auto"><GroupOptions groups={groups} value={groupId ?? "none"} onChange={setGroupId} /></div><Textarea value={note} onChange={event => setNote(event.target.value)} placeholder="Optional note" /><p className="text-xs text-muted-foreground">{matches.length} pathways match · {already} already in this group · {matches.length - already} will change</p><Collapsible open={expanded} onOpenChange={setExpanded}><CollapsibleTrigger asChild><Button variant="ghost" size="sm" className="px-0 text-xs"><ChevronRight className={cn("mr-1 h-3.5 w-3.5 transition-transform", expanded && "rotate-90")} />Matching pathways</Button></CollapsibleTrigger><CollapsibleContent className="max-h-40 space-y-1 overflow-y-auto rounded-md border p-2">{matches.map(item => <div key={item.id} className="flex items-center justify-between gap-3 text-xs"><code>{item.id}</code><GroupChip groupId={item.group_id} /></div>)}</CollapsibleContent></Collapsible><DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={matches.length - already === 0} onClick={() => { onSave(matches.map(item => item.id), groupId, note.trim() || null); onClose(); }}>Assign group</Button></DialogFooter></DialogContent></Dialog>; }


function BulkDeactivateDialog({ open, onClose, pathways }: { open: boolean; onClose: () => void; pathways: Pathway[] }) { const store = useHitlStore(); const [dimension, setDimension] = useState<"feedstock" | "product" | "application_market">("feedstock"); const values = [...new Set(pathways.map(item => item[dimension]))].sort(); const [value, setValue] = useState(""); const [status, setStatus] = useState<PathwayStatus>("locked"); const [visibility, setVisibility] = useState<VisibilityScope>("all"); const [note, setNote] = useState(""); useEffect(() => { setValue(values[0] ?? ""); }, [dimension]); const matches = pathways.filter(item => item[dimension] === value && item.status !== "deleted"); const save = () => { matches.forEach(item => { store.recordChange({ entity_type: "pathway", entity_id: item.id, field: "status", prior_value: item.status, new_value: status, operation: "deactivate", note }); if (JSON.stringify(item.visibility_scope) !== JSON.stringify(visibility)) store.recordChange({ entity_type: "pathway", entity_id: item.id, field: "visibility_scope", prior_value: item.visibility_scope, new_value: visibility, operation: "update", note }); }); toast.success(`${matches.length} pathways updated`); onClose(); }; return <Dialog open={open} onOpenChange={value => { if (!value) onClose(); }}><DialogContent><DialogHeader><DialogTitle>Bulk deactivate by node</DialogTitle><DialogDescription>Apply one status to every matching pathway.</DialogDescription></DialogHeader><div className="grid grid-cols-2 gap-3"><SimpleSelect value={dimension} onChange={value => setDimension(value as typeof dimension)} label="Dimension" className="w-full"><SelectItem value="feedstock">Feedstock</SelectItem><SelectItem value="product">Product</SelectItem><SelectItem value="application_market">{NODE_LABELS.application_market}</SelectItem></SimpleSelect><SimpleSelect value={value} onChange={setValue} label="Value" className="w-full">{values.map(item => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SimpleSelect></div><SimpleSelect value={status} onChange={value => setStatus(value as PathwayStatus)} label="Target status" className="w-full"><SelectItem value="locked">Locked</SelectItem><SelectItem value="hidden">Hidden</SelectItem><SelectItem value="deleted">Deleted</SelectItem></SimpleSelect><VisibilityControl value={visibility} onChange={setVisibility} /><Textarea value={note} onChange={event => setNote(event.target.value)} placeholder="Optional note" className="text-xs" /><div className="rounded-md bg-muted p-2 text-[10px]"><b>{matches.length} pathways match</b><div className="mt-1 font-mono text-muted-foreground">{matches.map(item => item.id).join(", ") || "—"}</div></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={!matches.length} onClick={save}>Confirm</Button></DialogFooter></DialogContent></Dialog>; }

type ImportRow = Draft & { result: "OK" | string; newNodes: NodeKey[] };
function ImportExcelDialog({ open, onClose, pathways }: { open: boolean; onClose: () => void; pathways: Pathway[] }) { const store = useHitlStore(); const input = useRef<HTMLInputElement>(null); const [rows, setRows] = useState<ImportRow[]>([]); const headers: Record<NodeKey, string> = NODE_LABELS; const legacyHeaders: Partial<Record<NodeKey, string>> = { process_technology: "Process/Technology", application_market: "Application/Market" }; const known = useMemo(() => Object.fromEntries((Object.keys(headers) as NodeKey[]).map(key => [key, new Set(pathways.map(item => clean(item[key])))])) as Record<NodeKey, Set<string>>, [pathways]); const parse = async (file: File) => { const book = XLSX.read(await file.arrayBuffer(), { type: "array" }); const sheet = book.Sheets[book.SheetNames[0]]; if (!sheet) return; const data = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet, { defval: "" }); const seen = new Set<string>(); setRows(data.map(raw => { const draft: Draft = { feedstock: String(raw[headers.feedstock] ?? "").trim(), process_technology: String(raw[headers.process_technology] ?? raw[legacyHeaders.process_technology ?? ""] ?? "").trim(), product: String(raw[headers.product] ?? "").trim(), application_market: String(raw[headers.application_market] ?? raw[legacyHeaders.application_market ?? ""] ?? "").trim(), group: String(raw.Group ?? "").trim() || null }; const missing = (Object.keys(headers) as NodeKey[]).find(key => !draft[key]); const key = (Object.keys(headers) as NodeKey[]).map(field => clean(draft[field])).join("|"); const duplicate = pathways.find(item => samePathway(item, draft)); let result = "OK"; if (missing) result = `Missing ${headers[missing]}`; else if (duplicate) result = `Duplicate of ${duplicate.id}`; else if (seen.has(key)) result = "Duplicate within file"; else seen.add(key); return { ...draft, result, newNodes: (Object.keys(headers) as NodeKey[]).filter(field => draft[field] && !known[field].has(clean(draft[field]))) }; })); }; const download = () => { const sheet = XLSX.utils.aoa_to_sheet([[...Object.values(headers), "Group"]]); const book = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(book, sheet, "Pathways"); XLSX.writeFile(book, "pathway-import-template.xlsx"); }; const save = () => { const valid = rows.filter(row => row.result === "OK"); valid.forEach((row, index) => { const now = new Date().toISOString(); const id = `pw-${String(Math.max(0, ...pathways.map(item => Number(item.id.match(/\d+/)?.[0] ?? 0))) + index + 1).padStart(3, "0")}`; const record: Pathway = { id, feedstock: row.feedstock, process_technology: row.process_technology, product: row.product, application_market: row.application_market, group: row.group, status: "needs_approval", visibility_scope: "all", created_at: now, updated_at: now, status_changed_at: now, last_actor: store.currentUser.name, trace_id: null }; store.recordChange({ entity_type: "pathway", entity_id: id, field: null, prior_value: null, new_value: record, operation: "create", note: "Imported from Excel; enrichment and matching queued" }); }); const errors = rows.filter(row => row.result.startsWith("Missing")).length; const skipped = rows.length - valid.length - errors; toast.success(`${valid.length} imported, ${skipped} skipped, ${errors} errors`); setRows([]); onClose(); }; return <Dialog open={open} onOpenChange={value => { if (!value) onClose(); }}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-4xl"><DialogHeader><DialogTitle>Import Excel</DialogTitle><DialogDescription>Upload the first sheet of an .xlsx workbook.</DialogDescription></DialogHeader><div className="flex items-center justify-center rounded-md border border-dashed p-8"><input ref={input} type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) void parse(file); }} /><Button variant="outline" onClick={() => input.current?.click()}><Upload className="mr-2 h-4 w-4" />Choose .xlsx file</Button></div><Button variant="link" className="h-auto w-fit p-0 text-xs" onClick={download}><Download className="mr-1 h-3 w-3" />Download template</Button>{rows.length > 0 && <div className="max-h-72 overflow-auto rounded-md border"><Table className="min-w-[900px]"><TableHeader><TableRow>{Object.values(headers).map(item => <TableHead key={item}>{item}</TableHead>)}<TableHead>Group</TableHead><TableHead>Result</TableHead></TableRow></TableHeader><TableBody>{rows.map((row, index) => <TableRow key={index}>{(Object.keys(headers) as NodeKey[]).map(key => <TableCell key={key} className="text-[10px]">{row[key]}{row.newNodes.includes(key) && <Badge variant="outline" className="ml-1 inline-flex h-6 items-center gap-1 whitespace-nowrap px-2 text-xs">New node</Badge>}</TableCell>)}<TableCell className="text-[10px]">{row.group ?? "—"}</TableCell><TableCell className={cn("text-[10px] font-medium", row.result === "OK" ? "text-primary" : row.result.startsWith("Missing") ? "text-destructive" : "text-warning-foreground")}>{row.result}</TableCell></TableRow>)}</TableBody></Table></div>}<DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={!rows.some(row => row.result === "OK")} onClick={save}>Import {rows.filter(row => row.result === "OK").length} rows</Button></DialogFooter></DialogContent></Dialog>; }